/**
 * 컴포넌트 base 이름 — 아키타입을 판정한 **키워드까지**를 잘라낸다.
 * 같은 아키타입이라도 서로 다른 컴포넌트를 구분하기 위한 것:
 *   button-primary48 → button       (키워드가 맨 앞)
 *   icon-button40    → icon-button  (앞에 수식어가 붙은 별개 컴포넌트)
 *   avatar56         → avatar
 *   status-dot-online→ status-dot
 * 키워드를 못 찾으면(=other) 사이즈·상태 접미사만 떼고 그대로 쓴다.
 */
export function specBaseName(name: string): string {
  const stripped = name.replace(SPEC_STATE_SUFFIX_RE, '').replace(/(\d{2,3})$/, '').replace(/-+$/, '');
  const rule = ARCHETYPE_RULES.find(([, re]) => re.test(name));
  if (!rule) return stripped || name;
  const m = stripped.match(rule[1]);
  if (!m || m.index === undefined) return stripped || name;
  // 매칭 끝까지 자르되 경계의 하이픈은 정리 (cell 규칙은 앞뒤 하이픈을 포함해 매칭한다)
  const cut = stripped.slice(0, m.index + m[0].length).replace(/-+$/, '');
  return cut || stripped || name;
}

/* ── 값 → 토큰 var 역매핑 ── */

const CATEGORY_ALIAS: Record<string, string> = {
  colors: 'color',
  color: 'color',
  rounded: 'radius',
  radius: 'radius',
  typography: 'typography',
  spacing: 'spacing',
  shadow: 'shadow',
};

const normalizeValue = (v: string): string => {
  const t = v.trim();
  // #AABBCC ↔ #aabbcc 동일 취급, #ABC → #aabbcc 확장
  const hex = t.match(/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/);
  if (!hex) return t.toLowerCase();
  const h = hex[1];
  return `#${(h.length === 3 ? h.split('').map((c) => c + c).join('') : h).toLowerCase()}`;
};

/**
 * 토큰 맵 → (정규화 값 → CSS 변수명). 같은 값이 여러 키에 있으면 카테고리·키 정렬 첫
 * 항목이 이긴다(결정성). typography 는 스칼라 값이 폰트 크기 등 범용이라 제외 —
 * 색·라운드·간격만 역매핑 대상.
 */
function buildValueToVar(tokens: DesignTokenMap): Map<string, string> {
  const map = new Map<string, string>();
  for (const cat of Object.keys(tokens).sort()) {
    if (cat === 'typography') continue;
    for (const key of Object.keys(tokens[cat]).sort()) {
      const v = normalizeValue(tokens[cat][key]);
      if (!map.has(v)) map.set(v, `--${cat}-${key}`);
    }
  }
  return map;
}

/** 스펙 값 → CSS 값 문자열. `{cat.key}` 참조와 리터럴 모두 토큰 var 로 정렬 */
function toCssValue(
  raw: string | undefined,
  tokens: DesignTokenMap,
  v2v: Map<string, string>,
  allowCats?: string[],
): string | null {
  if (!raw) return null;
  const t = raw.trim();
  if (!t) return null;
  const ref = t.match(/^\{([\w-]+)\.([\w.-]+)\}$/);
  if (ref) {
    const cat = CATEGORY_ALIAS[ref[1]] ?? ref[1];
    const key = ref[2].replace(/\./g, '-');
    // 참조가 실존 토큰일 때만 var — 없으면 원문(미해결 참조는 스타일 무효라 제외)
    return tokens[cat]?.[key] !== undefined ? `var(--${cat}-${key})` : null;
  }
  // 안전 게이트: CSS 값에 허용되지 않는 문자·외부 로드 구문 거절
  if (!/^[a-zA-Z0-9\s#%.,()'"/_-]{1,128}$/.test(t) || /url\s*\(|expression\s*\(|javascript:|\/\//i.test(t)) return null;
  const mapped = v2v.get(normalizeValue(t));
  if (!mapped) return t;
  // 값이 같아도 축이 다른 토큰이면 쓰지 않는다 — 의미가 어긋나면 리터럴이 낫다
  if (allowCats && !allowCats.some((c) => mapped.startsWith(`--${c}-`))) return t;
  return `var(${mapped})`;
}

/** typography 참조 → 평탄화 키 기반 개별 CSS 속성 (축약 font: 금지) */
const TYPO_PROPS: Array<[string, string]> = [
  ['font-size', 'fontSize'],
  ['font-weight', 'fontWeight'],
  ['line-height', 'lineHeight'],
  ['letter-spacing', 'letterSpacing'],
  ['font-family', 'fontFamily'],
];

function typographyStyle(raw: string | undefined, tokens: DesignTokenMap): Array<[string, string]> {
  if (!raw) return [];
  const m = raw.trim().match(/^\{typography\.([\w.-]+)\}$/);
  if (!m) return [];
  const role = m[1].replace(/\./g, '-');
  const out: Array<[string, string]> = [];
  for (const [suffix, cssProp] of TYPO_PROPS) {
    if (tokens.typography?.[`${role}-${suffix}`] !== undefined) {
      out.push([cssProp, `var(--typography-${role}-${suffix})`]);
    }
  }
  return out;
}

/** 스펙 prop → CSS 속성 매핑 (형태에 직접 기여하는 것만) */
/**
 * 리터럴 값을 토큰으로 되돌릴 때 찾아볼 카테고리.
 * 제한하지 않으면 height:64px 이 radius-3xl(같은 64px)로 매칭돼, 라운드 토큰을 조정하면
 * 버튼 높이가 따라 변하는 엉뚱한 결합이 생긴다. 없으면 리터럴로 두는 편이 안전하다.
 */
const REVERSE_LOOKUP_CATS: Record<string, string[]> = {
  backgroundColor: ['color', 'primitive'],
  textColor: ['color', 'primitive'],
  borderColor: ['color', 'primitive'],
  rounded: ['radius'],
  radius: ['radius'],
  padding: ['spacing'],
  height: ['spacing', 'size'],
  width: ['spacing', 'size'],
  size: ['spacing', 'size'],
};

export const SPEC_STYLE_PROPS: Array<[string, string]> = [
  ['backgroundColor', 'backgroundColor'],
  ['textColor', 'color'],
  ['borderColor', 'borderColor'],
  ['rounded', 'borderRadius'],
  ['radius', 'borderRadius'],
  ['padding', 'padding'],
  ['height', 'height'],
  ['width', 'width'],
];

function specToStyle(
  e: SpecEntry | undefined,
  tokens: DesignTokenMap,
  v2v: Map<string, string>,
  skip: Set<string> = new Set(),
): Array<[string, string]> {
  if (!e) return [];
  const out: Array<[string, string]> = [];
  for (const [prop, css] of SPEC_STYLE_PROPS) {
    if (skip.has(css)) continue;
    const v = toCssValue(e.props[prop], tokens, v2v, REVERSE_LOOKUP_CATS[prop]);
    if (v !== null) out.push([css, v]);
  }
  if (!skip.has('font')) out.push(...typographyStyle(e.props.typography, tokens));
  if (e.props.borderColor && !skip.has('borderStyle')) out.push(['borderStyle', 'solid'], ['borderWidth', '1px']);
  return out;
}

