export interface VariantGroup {
  key: string;
  base?: SpecEntry;
  states: Record<string, SpecEntry>;
}

export interface ArchGroup {
  arch: Archetype;
  variants: VariantGroup[];
  sizes: Array<[string, SpecEntry]>;
  entries: SpecEntry[];
  /**
   * 변형에 속하지 않는 컴포넌트 전역 상태(`button-disabled` 처럼 변형 이름 없이 상태만 있는 엔트리).
   * 예전에는 base 가 없다는 이유로 통째로 버려져, Properties 에는 보이는 disabled 가
   * 생성 코드에는 빠져 있었다.
   */
  globalStates: Record<string, SpecEntry>;
}

/** `button-primary48` → {variant:'primary', size:'48'} / `button-primary-hover` → state */
/**
 * 스펙 엔트리를 변형·크기·상태 축으로 가른다.
 * `prefix` 는 변형 키에서 떼어낼 앞부분 — 아키타입 이름(button) 또는 base 이름(icon-button).
 * 가이드 견본은 아키타입을, 생성기는 base 를 넘긴다.
 */
export function groupEntries(prefix: Archetype | string, list: SpecEntry[]): ArchGroup {
  const arch = prefix as Archetype;
  const variants = new Map<string, VariantGroup>();
  const sizes = new Map<string, SpecEntry>();
  for (const e of list) {
    const state = e.name.match(SPEC_STATE_SUFFIX_RE)?.[1];
    const stripped = e.name.replace(SPEC_STATE_SUFFIX_RE, '');
    const sizeM = stripped.match(/^(.*?)(\d{2,3})$/);
    const rawKey = (sizeM ? sizeM[1] : stripped).replace(new RegExp(`^${arch}-?`), '') || 'default';
    const key = rawKey.replace(/-+$/, '') || 'default';
    if (sizeM && !state && !sizes.has(sizeM[2])) sizes.set(sizeM[2], e);
    const v = variants.get(key) ?? { key, states: {} };
    if (state) v.states[state] = e;
    else if (!v.base) v.base = e;
    variants.set(key, v);
  }
  const globalStates: Record<string, SpecEntry> = {};
  for (const v of variants.values()) {
    if (v.base) continue;
    for (const [st, e] of Object.entries(v.states)) if (!globalStates[st]) globalStates[st] = e;
  }
  return {
    arch,
    variants: [...variants.values()].filter((v) => v.base),
    sizes: [...sizes.entries()].sort((a, b) => Number(b[0]) - Number(a[0])),
    entries: list,
    globalStates,
  };
}

